def transform(grid):
    n, m = len(grid), len(grid[0])
    points = [(c - r, value) for r, row in enumerate(grid) for c, value in enumerate(row) if value != 0]
    for period in range(1, max(n, m) + 1):
        phases = {}
        valid = True
        for diagonal, value in points:
            phase = diagonal % period
            if phase in phases and phases[phase] != value:
                valid = False
                break
            phases[phase] = value
        if valid:
            return [[phases[(c-r) % period] for c in range(m)] for r in range(n)]
    raise ValueError("No consistent diagonal period found")

